<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Device\Domain;

use DateTimeImmutable;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;

final class DeviceAuthorization
{
    public function __construct(
        public readonly string $deviceCode,
        public readonly string $userCode,
        public readonly string $tenant,
        public readonly string $clientId,
        public readonly string $scope,
        public readonly array $audiences,
        public readonly int $interval,
        public readonly DateTimeImmutable $requestedAt,
        public readonly DateTimeImmutable $expiresAt,
        public readonly string $status,
        public readonly ?AuthenticationResult $auth,
        public readonly ?DateTimeImmutable $lastPollAt
    ) {
    }

    public function isExpired(DateTimeImmutable $now): bool
    {
        return $now > $this->expiresAt;
    }

    public function expiresIn(DateTimeImmutable $now): int
    {
        $diff = $this->expiresAt->getTimestamp() - $now->getTimestamp();
        return $diff > 0 ? $diff : 0;
    }
}
